/** Error factories of the container (internal): one place for codes, messages and hints. */

import type { ZnightMetadata } from './metadata.ts'
import type { Slot } from './slot.ts'

import { ErrorCode, ZnightError } from './errors.ts'
import { describeKey, describeToken } from './tokens.ts'

/** Why a resolution cannot proceed, from the container status. */
export type Unavailability = 'open' | 'failed' | 'disposed'

export function invalidMetadataError(): ZnightError {
  return new ZnightError(
    ErrorCode.VersionMismatch,
    'Invalid metadata: expected the object generated by @znight/compiler ({ version, providers, resolutionOrder })',
  )
}

export function metadataVersionError(metadata: ZnightMetadata, expected: number): ZnightError {
  const compiler = metadata.compiler === undefined ? '' : ` (generated by @znight/compiler ${metadata.compiler})`
  return new ZnightError(
    ErrorCode.VersionMismatch,
    `Unsupported metadata version ${String(metadata.version)}${compiler}: @znight/core expects version ${expected}`,
    { hints: ['Regenerate the metadata (znight generate) with a @znight/compiler version matching @znight/core'] },
  )
}

function providedBy(slot: Slot | undefined): string {
  const plugin = slot?.external?.providedBy
  return plugin === undefined ? '' : ` (provided by ${plugin})`
}

export function notFoundError(key: unknown, slot?: Slot): ZnightError {
  const hints: string[] = []
  const plugin = slot?.external?.providedBy
  if (plugin !== undefined) hints.push(`Add ${plugin} to Application.create({ plugins })`)
  if (typeof key === 'function') {
    hints.push(`Decorate ${key.name || 'the class'} with @Injectable() and regenerate the metadata (znight generate)`)
  } else {
    hints.push('Supply it with Application.create({ providers }) or container.registerValue()')
  }
  return new ZnightError(ErrorCode.MissingProvider, `No provider for ${describeKey(key)}${providedBy(slot)}`, {
    hints,
  })
}

export function unknownClassError(action: string, key: unknown): ZnightError {
  return new ZnightError(
    ErrorCode.MissingProvider,
    `Cannot ${action} ${describeKey(key)}: it is not a known provider`,
    {
      hints: ['Pass the provider token, or a class registered in the compiled metadata'],
    },
  )
}

export function ambiguousNameError(name: string, matches: readonly Slot[]): ZnightError {
  return new ZnightError(
    ErrorCode.AmbiguousInjection,
    `"${name}" is ambiguous: it matches ${matches.map(slot => slot.token).join(', ')}`,
    { hints: ['Use the class or the full token instead of the display name'] },
  )
}

export function noScopeError(slot: Slot): ZnightError {
  return new ZnightError(
    ErrorCode.NoActiveScope,
    `${describeToken(slot.token)} is request-scoped and was resolved outside of a request scope`,
    {
      hints: [
        'Resolve it inside container.runInScope()',
        'In singletons, inject it as Lazy<T> and call get() during the request',
      ],
    },
  )
}

export function closedScopeError(slot: Slot): ZnightError {
  return new ZnightError(
    ErrorCode.NoActiveScope,
    `${describeToken(slot.token)} was resolved in a request scope that is already closed`,
    { hints: ['Await every asynchronous operation of a request inside the runInScope() callback'] },
  )
}

export function missingScopeValueError(slot: Slot): ZnightError {
  return new ZnightError(
    ErrorCode.NoActiveScope,
    `No value for the request-scoped ${describeToken(slot.token)} in the current scope${providedBy(slot)}`,
    { hints: ['Pass it to container.runInScope(fn, [[token, value]]) or set it with currentScope().set()'] },
  )
}

export function sealedError(action: string, key: unknown): ZnightError {
  return new ZnightError(
    ErrorCode.ContainerSealed,
    `Cannot ${action} ${describeKey(key)}: the container is sealed (init() has been called)`,
    { hints: ['Register providers, values and overrides before init(), e.g. in Plugin.register()'] },
  )
}

export function duplicateRegistrationError(action: string, slot: Slot): ZnightError {
  return new ZnightError(
    ErrorCode.DuplicateProvider,
    `Cannot ${action} ${describeToken(slot.token)}: it is already registered by ${slot.origin ?? 'another registration'}`,
    { hints: ['Use container.override() (or Application.create({ overrides })) to replace a provider'] },
  )
}

export function compiledProviderError(action: string, slot: Slot): ZnightError {
  const source = slot.compiledSource
  const where = source === undefined ? '' : ` declared at ${source.file}:${source.line}:${source.column}`
  return new ZnightError(
    ErrorCode.DuplicateProvider,
    `Cannot ${action} ${describeToken(slot.token)}: it is a compiled provider${where}`,
    { hints: ['Use container.override() to replace a compiled provider'] },
  )
}

export function unavailableError(slot: Slot, reason: Unavailability): ZnightError {
  switch (reason) {
    case 'disposed':
      return new ZnightError(
        ErrorCode.InstantiationFailed,
        `Cannot resolve ${slot.displayName}: the container has been disposed`,
      )
    case 'failed':
      return new ZnightError(
        ErrorCode.InstantiationFailed,
        `Cannot resolve ${slot.displayName}: the container failed to initialise`,
      )
    default:
      return new ZnightError(
        ErrorCode.InstantiationFailed,
        `Cannot resolve ${slot.displayName}: the container is not initialised`,
        { hints: ['Call `await container.init()` (or use Application.create()) first'] },
      )
  }
}

export function reentrantCreationError(slot: Slot): ZnightError {
  return new ZnightError(
    ErrorCode.CircularDependency,
    `Circular dependency: ${slot.displayName} was requested while it is being instantiated`,
    { hints: ['Do not call Lazy<T>.get() from a constructor or factory: call it later (e.g. in onStart())'] },
  )
}

export function notReadyError(slot: Slot): ZnightError {
  return new ZnightError(
    ErrorCode.InstantiationFailed,
    `${slot.displayName} is not ready yet: its async factory is still running`,
    { hints: ['Call Lazy<T>.get() after init() completed (e.g. in onStart())'] },
  )
}

export function failedProviderError(slot: Slot): ZnightError {
  return new ZnightError(ErrorCode.InstantiationFailed, `${slot.displayName} failed to initialise`)
}

export function asyncOnDemandError(slot: Slot, declared: boolean): ZnightError {
  return new ZnightError(
    ErrorCode.InstantiationFailed,
    declared
      ? `Cannot create ${slot.displayName} on demand: its factory is async`
      : `Cannot create ${slot.displayName} on demand: its factory returned a promise`,
    {
      hints: [
        declared
          ? 'Include it in init({ only }) so that it is created during initialisation'
          : 'Declare it async and include it in init({ only })',
      ],
    },
  )
}
